#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

DATABASE_NAME="weekend-deals"

# Runs one SQL statement over Turso's HTTP API; the token goes in through stdin, so it never shows up in `ps`.
# The Turso tool exits with 0 even when it refuses ("You are not logged in"), so its output tells what happened.
logged_in() {
  local who
  who=$(turso auth whoami 2>&1 || true)
  [[ -n "$who" && "$who" != *"not logged in"* ]]
}
database_url() { turso db show "$DATABASE_NAME" --url 2>/dev/null | grep -oE 'libsql://[^[:space:]]+' | head -n1 || true; }
# A JWT: three base64url parts; long ones, so a dotted host name in a message never passes for one.
TOKEN_PATTERN='[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}'

TEST_ERROR=""
test_database() {
  local http_url response status
  TEST_ERROR=""
  [[ -n "$TURSO_DATABASE_URL" ]] || { TEST_ERROR="geen database-adres"; return 1; }
  http_url="https://${TURSO_DATABASE_URL#libsql://}/v2/pipeline"
  response=$(printf 'Authorization: Bearer %s\n' "$TURSO_AUTH_TOKEN" | curl -sS -w '\n%{http_code}' \
    -X POST "$http_url" -H @- -H 'Content-Type: application/json' \
    -d '{"requests":[{"type":"execute","stmt":{"sql":"SELECT 1"}},{"type":"close"}]}') || { TEST_ERROR="geen verbinding met Turso"; return 1; }
  status=${response##*$'\n'}
  [[ "$status" == 200 ]] && return 0
  TEST_ERROR="Turso antwoordde $status"
  return 1
}

run_wizard() {

TOTAL_STAGES=6
ENV_FILE="$(cd "$(dirname "$0")/.." && pwd)/.env.local"
PROJECT_DIR="$(cd "$(dirname "$0")/.." && pwd)"

banner "Turso: de prijzen van Weekendje weg in de cloud"

stage "Turso-opdrachtregeltool"
say "Met deze tool maakt het script je database en sleutel aan, zodat je niets hoeft over te typen."
if command -v turso >/dev/null 2>&1; then
  printf '  %s✓ Turso-tool is al geïnstalleerd%s\n' "$GREEN" "$RESET"
elif command -v brew >/dev/null 2>&1; then
  note "De tool komt uit twee Homebrew-bronnen van Turso: tursodatabase/tap en libsql/sqld."
  note "Homebrew installeert alleen wat je vertrouwt. Na je ja voegt dit script libsql/sqld toe en"
  note "vertrouwt het daaruit alleen de formule sqld, die de Turso-tool nodig heeft."
  if confirm "Bronnen toevoegen, sqld vertrouwen en de Turso-tool installeren?"; then
    # The turso formula depends on sqld from Turso's second tap; Homebrew loads it only once that formula is trusted.
    if ! { brew tap libsql/sqld && brew trust --formula libsql/sqld/sqld && brew install tursodatabase/tap/turso; }; then
      warn "Installeren lukte niet; zie de melding van Homebrew hierboven. Los dat op en start opnieuw."
      exit 1
    fi
  else
    warn "Zonder de tool kan dit script niet verder. Installeer hem later en start opnieuw."
    exit 1
  fi
else
  warn "Homebrew ontbreekt. Installeer de tool zelf: https://docs.turso.tech/cli/installation"
  exit 1
fi
pause "Druk op Enter."

stage "Inloggen bij Turso"
if logged_in; then
  printf '  %s✓ Je bent al ingelogd als %s%s\n' "$GREEN" "$(turso auth whoami 2>/dev/null)" "$RESET"
else
  say "Turso opent je browser. Een account is gratis en vraagt geen creditcard."
  if confirm "Heb je al een Turso-account?"; then
    turso auth login || true
  else
    turso auth signup || true
  fi
  until logged_in; do
    warn "Turso meldt dat je nog niet bent ingelogd."
    confirm "Opnieuw inloggen?" || exit 1
    turso auth login || true
  done
  printf '  %s✓ Ingelogd als %s%s\n' "$GREEN" "$(turso auth whoami 2>/dev/null)" "$RESET"
fi
pause "Druk op Enter."

stage "Database aanmaken"
if [[ -n "$(database_url)" ]]; then
  printf '  %s✓ Database "%s" bestaat al; die gebruiken we%s\n' "$GREEN" "$DATABASE_NAME" "$RESET"
else
  say "Turso kiest zelf een locatie dicht bij je."
  turso db create "$DATABASE_NAME" || true
  if [[ -z "$(database_url)" ]]; then
    warn "Aanmaken lukte niet; zie de melding van Turso hierboven. Los dat op en start opnieuw."
    exit 1
  fi
  printf '  %s✓ Database "%s" aangemaakt%s\n' "$GREEN" "$DATABASE_NAME" "$RESET"
fi
pause "Druk op Enter."

stage "Adres van de database"
TURSO_DATABASE_URL=$(database_url)
until [[ "$TURSO_DATABASE_URL" =~ ^libsql://[^[:space:]]+$ ]]; do
  warn "Het adres kon niet automatisch worden gelezen."
  step "Draai in een ander venster: turso db show $DATABASE_NAME --url"
  ask TURSO_DATABASE_URL "Plak het adres (begint met libsql://):" || exit 1
done
write_env TURSO_DATABASE_URL "$TURSO_DATABASE_URL"
pause "Druk op Enter."

stage "Sleutel aanmaken"
say "Een sleutel met lees- en schrijfrechten voor alleen deze database. Hij komt alleen in .env.local."
TURSO_AUTH_TOKEN=$(turso db tokens create "$DATABASE_NAME" 2>/dev/null | grep -oE "$TOKEN_PATTERN" | head -n1 || true)
until [[ "$TURSO_AUTH_TOKEN" =~ ^${TOKEN_PATTERN}$ ]]; do
  warn "De sleutel kon niet automatisch worden gelezen."
  step "Draai in een ander venster: turso db tokens create $DATABASE_NAME"
  ask_secret TURSO_AUTH_TOKEN "Plak de sleutel (onzichtbaar):" || exit 1
done
printf '  %s✓ Sleutel aangemaakt%s\n' "$GREEN" "$RESET"
pause "Druk op Enter voor de test."

stage "Testen en gegevens overzetten"
until test_database; do
  warn "Verbinding lukt nog niet: $TEST_ERROR"
  confirm "Opnieuw proberen?" || break
done
if [[ -z "$TEST_ERROR" ]]; then
  printf '  %s✓ Turso accepteert de sleutel%s\n' "$GREEN" "$RESET"
  write_env TURSO_AUTH_TOKEN "$TURSO_AUTH_TOKEN"
  if [[ -f "$PROJECT_DIR/data/prices.db" ]] && confirm "Je huidige prijzen (data/prices.db) naar Turso kopiëren?"; then
    (cd "$PROJECT_DIR" && npm run -s storage:copy) || SKIPPED+=("prijzen kopiëren mislukt: probeer het later met npm run storage:copy")
  fi
else
  SKIPPED+=("TURSO_AUTH_TOKEN niet bewaard: start het script opnieuw zodra de verbinding werkt")
fi
pause "Druk op Enter."

finish
say "Herstart de app (npm run dev); hij gebruikt dan Turso in plaats van het lokale bestand."
say "De achtergrondtaak op je Mac schrijft voortaan ook naar Turso."
printf '\n'
}

run_wizard "$@"; exit
